//#if LockedProportions        [CategoryAttribute("POLOHA A VELIKOST"),            DisplayName("Poloměr"),            DescriptionAttribute("Poloměr kruhu"),            RefreshProperties(RefreshProperties.All),            Browsable(false)        ]        int Radius { get; set; }//#else        [CategoryAttribute("POLOHA A VELIKOST"),             DisplayName("Velikost"),             DescriptionAttribute("Velikost elipsy"),             RefreshProperties(RefreshProperties.All),             Browsable(false)         ]        Size Size { get; set; }//#endif        public int Radius {            get { return Width / 2; }            set { Width = Height = value * 2; UpdateResizer(); }        }        new public Size Size {            get {                return new Size(Width, Height);            }            set {                SetBounds(Location.X, Location.Y, value.Width, value.Height, BoundsSpecified.Size);                UpdateResizer();            }        }            SetBrowsableAttributeValue(nameof(Radius), LockedProportions);            SetBrowsableAttributeValue(nameof(Size), !LockedProportions);        private void SetBrowsableAttributeValue(string attribute, bool value) {            var descriptor = TypeDescriptor.GetProperties(GetType())[attribute];            var attrib = (BrowsableAttribute)descriptor.Attributes[typeof(BrowsableAttribute)];            var isBrow = attrib.GetType().GetField("browsable", BindingFlags.NonPublic | BindingFlags.Instance);            isBrow.SetValue(attrib, value);        }